"""Shared, explicitly proposed OS architecture for the laptop and public showcase."""
import streamlit.components.v1 as components
from visuals import logo


def architecture():
    tools = [('theo-icon.png','Theo','Science & predictions','#9275ff'),
             ('pasqal-icon.png','PASQAL','Atoms & quantum control','#50dbef'),
             ('qbraid-icon.png','qBraid / IQM','Circuits & measurements','#c48aff'),
             ('grok.svg','Specialist agents','GPT · Claude · Grok','#5fe0b5')]
    cards = ''.join(f'<div class="tool" style="--accent:{colour}"><img alt="{name}" src="{logo(asset)}"><b>{name}</b><span>{purpose}</span></div>' for asset,name,purpose,colour in tools)
    interfaces = ''.join(f'<div class="client {style}"><img alt="{name}" src="{logo(asset)}"><b>{name}</b></div>' for asset,name,style in [('openai.svg','ChatGPT','gpt'),('claude.png','Claude','claude')])
    person = '''<svg role="img" aria-label="A person at their laptop" viewBox="0 0 140 110"><defs><linearGradient id="shirt"><stop stop-color="#76e4ff"/><stop offset="1" stop-color="#7863ff"/></linearGradient></defs><circle cx="70" cy="23" r="15" fill="#ffd3b4"/><path d="M55 20c-3-25 39-25 30 5-2-12-19-6-23-15z" fill="#394175"/><path d="M35 82V65c0-27 70-27 70 0v17z" fill="url(#shirt)"/><rect x="40" y="62" width="60" height="38" rx="5" fill="#1a2446" stroke="#b0eaff" stroke-width="2"/><circle cx="70" cy="80" r="4" fill="#6ce3ff"/><path d="M30 102h80" stroke="#c6d7f9" stroke-width="5" stroke-linecap="round"/></svg>'''
    html = '''<!doctype html><html><head><style>
    *{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;color:#eef4ff;background:#0b1229;border-radius:22px;overflow:hidden}
    .os{padding:24px 26px;background:radial-gradient(ellipse at 65% 25%,#44369477,transparent 65%)}
    .eyebrow{color:#79e2ff;letter-spacing:2px;font-size:11px}.headline{font-size:25px;margin:10px 0 5px;font-weight:700}.sub{color:#b6c7e7;font-size:12px;line-height:1.5}
    .entry{display:grid;grid-template-columns:120px 28px 1fr 36px 1.15fr;align-items:center;gap:8px;margin:22px 0 10px}.person{text-align:center}.person svg{height:94px;width:115px}.person b{display:block;font-size:13px}.person span{font-size:10px;color:#a9bde1}
    .arrow{text-align:center;color:#72e5ff;font-size:25px}.interfaces{padding:14px;border:1px solid #9e8fff66;border-radius:16px;background:#ffffff07}.label{text-align:center;font-size:10px;letter-spacing:1.3px;color:#c0cbed;margin-bottom:10px}.clients{display:flex;gap:8px}.client{flex:1;display:flex;align-items:center;justify-content:center;gap:7px;padding:10px 5px;border-radius:10px;font-size:12px}.gpt{background:#13b69724;border:1px solid #40d3b166}.claude{background:#d9916a24;border:1px solid #efa68066}.client img{width:26px;height:26px;object-fit:contain;background:white;padding:4px;border-radius:7px}.other{text-align:center;color:#aebde0;font-size:10px;margin-top:9px}
    .core{padding:20px 12px;text-align:center;border:1px solid #71dfff;border-radius:16px;box-shadow:0 0 28px #55cfff20;background:#21417055}.core b{font-size:20px;display:block}.core span{display:block;font-size:11px;color:#b9cee9;margin-top:9px;line-height:1.5}.return{font-size:10px;color:#a6c0df;text-align:center;margin:10px 0 16px}
    .bus{height:18px;width:83%;margin:auto;border-top:1px solid #66dcff77;position:relative}.bus:before{content:'';position:absolute;left:75%;height:17px;top:-17px;border-left:1px solid #66dcff}
    .tools{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.tool{display:flex;align-items:center;flex-direction:column;gap:7px;padding:13px 5px;background:#ffffff07;border:1px solid #ffffff18;border-top:3px solid var(--accent);border-radius:12px}.tool img{height:32px;width:38px;object-fit:contain;background:white;padding:5px;border-radius:8px}.tool b{font-size:13px}.tool span{color:#b2c4e3;font-size:10px;text-align:center}
    .supports{display:grid;grid-template-columns:repeat(4,1fr);height:17px;margin:0 12%}.supports i{border-left:1px solid #f1ba7566;justify-self:center}
    .backbone{display:flex;align-items:center;gap:16px;padding:15px 20px;border-radius:14px;border:1px solid #edb86d99;background:linear-gradient(100deg,#eaae5922,#6e52a733);box-shadow:0 0 25px #dcb36f0b}.backbone img{width:37px;height:37px;background:white;border-radius:9px;padding:5px;object-fit:contain}.backbone b{font-size:17px;display:block;color:#ffd39b}.backbone span{font-size:11px;color:#d2dcf0;line-height:1.7}.foot{font-size:10px;color:#9db0d1;text-align:center;line-height:1.5;margin-top:12px}
    @media(max-width:650px){.os{padding:18px 12px}.entry{grid-template-columns:76px 16px 1fr 20px 1fr;gap:3px}.person svg{width:75px;height:75px}.clients{flex-direction:column;gap:5px}.interfaces{padding:9px 5px}.core{padding:18px 6px}.core b{font-size:15px}.headline{font-size:21px}.tool b{font-size:11px}.tool span{font-size:9px}.backbone{padding:12px;gap:10px}}
    </style></head><body><div class="os"><div class="eyebrow">PEOPLE FIRST · INTERFACE OF YOUR CHOICE</div><div class="headline">Your favourite AI. One shared Quantonation OS.</div><div class="sub">Every team member can ask, orchestrate and review through their preferred assistant.</div><div class="entry"><div class="person">'''+person+'''<b>Team member</b><span>Question · judgement · approval</span></div><div class="arrow">→</div><div class="interfaces"><div class="label">CHOOSE YOUR INTERFACE</div><div class="clients">'''+interfaces+'''</div><div class="other">Other compatible AI clients</div></div><div class="arrow">↔</div><div class="core"><b>QUANTONATION OS</b><span>Shared tools, agents & research workspaces<br>Prefect · task registry · scoped access</span></div></div><div class="return">← Results, evidence and requests for approval return to your chosen interface</div><div class="bus"></div><div class="tools">'''+cards+'''</div><div class="supports"><i></i><i></i><i></i><i></i></div><div class="backbone"><img alt="GitHub" src="'''+logo('github.png')+'''"><div><b>GitHub · the research backbone</b><span>Versioned tool & agent specs · source & tests · reviewed knowledge · branches & pull requests<br>Public showcase + private fund workspaces</span></div></div><div class="foot">Proposed client connections require authenticated integrations and workspace permissions.<br>Architecture vision · laptop rehearsal is implemented; ChatGPT / Claude connections are not yet deployed. Runtime state stays in the task registry.</div></div></body></html>'''
    components.html(html,height=650)
